import time
from concurrent.futures import ThreadPoolExecutor

import pytest


class Bad(Exception):
    def __init__(self, n: int) -> None:
        self.n = n


def check(x: int) -> int:
    """Return x if it is even; raise Bad(x) if it is odd."""
    if x % 2 == 1:
        raise Bad(x)
    return x


def all_even(xs: list[int]) -> list[int]:
    """Run check on every element of xs in a thread pool and return the results in input order.

    If any element is odd, raise Bad for the odd element with the lowest index,
    regardless of which thread finishes first. Return [] for an empty input.
    """
    with ThreadPoolExecutor() as pool:
        futures = [pool.submit(check, x) for x in xs]
        # Reading results in submission order raises the lowest-index Bad first.
        return [f.result() for f in futures]


def test_all_even_returns_values_in_order() -> None:
    assert all_even([2, 4, 6]) == [2, 4, 6]


def test_all_even_empty() -> None:
    assert all_even([]) == []


def test_all_even_single_odd() -> None:
    with pytest.raises(Bad) as exc:
        all_even([4, 3, 8])
    assert exc.value.n == 3


def test_all_even_reports_lowest_index_bad() -> None:
    with pytest.raises(Bad) as exc:
        all_even([1, 2, 3])
    assert exc.value.n == 1


def test_all_even_lowest_index_wins_even_if_finished_last(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    def slow_check(x: int) -> int:
        if x == 1:
            time.sleep(0.2)
        # Note: mypy --strict flags check.__wrapped__ (no such attribute on the function type).
        return check.__wrapped__(x) if hasattr(check, "__wrapped__") else _plain_check(x)

    def _plain_check(x: int) -> int:
        if x % 2 == 1:
            raise Bad(x)
        return x

    monkeypatch.setitem(globals(), "check", slow_check)
    with pytest.raises(Bad) as exc:
        all_even([1, 3, 4, 5])
    assert exc.value.n == 1
